/**
 * Slack Node - Version 1
 * Discriminator: resource=star, operation=delete
 */


interface Credentials {
  slackApi: CredentialReference;
  slackOAuth2Api: CredentialReference;
}

/** Deletes a message */
export type SlackV1StarDeleteParams = {
  resource: 'star';
  operation: 'delete';
  authentication?: 'accessToken' | 'oAuth2' | Expression<string>;
/**
 * Options to set
 * @default {}
 */
    options?: {
    /** Channel to add star to, or channel where the message to add star to was posted (used with timestamp). Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;.
     * @loadOptionsMethod getChannels
     */
    channelId?: string | Expression<string>;
    /** File to add star to
     */
    fileId?: string | Expression<string>;
    /** File comment to add star to
     */
    fileComment?: string | Expression<string>;
    /** Timestamp of the message to add star to
     */
    timestamp?: string | Expression<string>;
  };
};

export type SlackV1StarDeleteNode = {
  type: 'n8n-nodes-base.slack';
  version: 1;
  config: NodeConfig<SlackV1StarDeleteParams> & { credentials?: Credentials };
};